public class InnerGatewayTargetPrivateEndpointFactory(Action<Humidifier.BedrockAgentCore.GatewayTargetTypes.PrivateEndpoint> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayTargetTypes.PrivateEndpoint>
{

    internal InnerGatewayTargetManagedVpcResourceFactory ManagedVpcResourceFactory { get; set; }

    internal InnerGatewayTargetSelfManagedLatticeResourceFactory SelfManagedLatticeResourceFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTargetTypes.PrivateEndpoint Create()
    {
        var privateEndpointResult = CreatePrivateEndpoint();
        factoryAction?.Invoke(privateEndpointResult);

        return privateEndpointResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTargetTypes.PrivateEndpoint CreatePrivateEndpoint()
    {
        var privateEndpointResult = new Humidifier.BedrockAgentCore.GatewayTargetTypes.PrivateEndpoint();

        return privateEndpointResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTargetTypes.PrivateEndpoint result)
    {
        base.CreateChildren(result);

        result.ManagedVpcResource ??= ManagedVpcResourceFactory?.Build();
        result.SelfManagedLatticeResource ??= SelfManagedLatticeResourceFactory?.Build();
    }

} // End Of Class

